+// intent_apply_tick_raw — the edit fast-path convention for non-draw intents:
+// a command fired at at_ms applies at the NEXT tick boundary (floor + 1), like
+// draw/demolish — live + replay converge at the step boundary.
+intent_apply_tick_raw :: proc(at_ms: i64, logic_hz: i32) -> u64 {
+	return u64(max(0, at_ms * i64(logic_hz) / 1000)) + 1
+}

